            { id: 3, name: "Michael Brown", email: "michael@example.com", role: "User", status: "active", lastActive: "2023-06-12" },
            { id: 4, name: "Sarah Davis", email: "sarah@example.com", role: "Editor", status: "inactive", lastActive: "2023-06-10" },
            { id: 5, name: "Robert Wilson", email: "robert@example.com", role: "User", status: "active", lastActive: "2023-06-08" }
        ];

