        const fetchDataBtn = document.getElementById('fetch-data-btn');
        const userForm = document.getElementById('user-form');
        const searchInput = document.getElementById('search-input');
        const searchBtn = document.getElementById('search-btn');
        const dataFilter = document.getElementById('data-filter');

        // Initialize with sample data
        function renderData(data) {
            dataBody.innerHTML = '';
            data.forEach(item => {
                const row = document.createElement('tr');
                row.innerHTML = `
                    <td>${item.id}</td>
                    <td>${item.name}</td>
                    <td>${item.email}</td>
                    <td>${item.role}</td>
                    <td><span class="status status-${item.status}">${item.status.charAt(0).toUpperCase() + item.status.slice(1)}</span></td>
                    <td>${item.lastActive}</td>
                `;
                dataBody.appendChild(row);
            });
        }

        // Fetch data from API (simulated)
        fetchDataBtn.addEventListener('click', function() {
            this.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Loading...';

            setTimeout(() => {
                renderData(sampleData);
                this.innerHTML = '<i class="fas fa-download"></i> Fetch Data';

                // Update stats
                document.getElementById('user-count').textContent = sampleData.length;
                document.getElementById('order-count').textContent = Math.floor(Math.random() * 500) + 200;
                document.getElementById('revenue').textContent = '$' + (Math.random() * 100000).toFixed(0);
            }, 1000);
        });

        // Handle form submission
        userForm.addEventListener('submit', function(e) {
            e.preventDefault();

            const name = document.getElementById('name').value;
            const email = document.getElementById('email').value;
            const role = document.getElementById('role').value;

            if (name && email) {
                alert(`User ${name} added successfully!`);
                userForm.reset();
            }
        });

        // Search functionality
        searchBtn.addEventListener('click', function() {
            const searchTerm = searchInput.value.toLowerCase();
            const rows = dataBody.querySelectorAll('tr');

            rows.forEach(row => {
                const text = row.textContent.toLowerCase();
                row.style.display = text.includes(searchTerm) ? '' : 'none';
            });
        });

        // Filter functionality
        dataFilter.addEventListener('change', function() {
            const filterValue = this.value;
            const rows = dataBody.querySelectorAll('tr');

            rows.forEach(row => {
                const statusCell = row.querySelector('.status');
                if (filterValue === 'all' || 
                    (filterValue === 'active' && statusCell.classList.contains('status-active')) ||
                    (filterValue === 'pending' && statusCell.classList.contains('status-pending')) ||
                    (filterValue === 'inactive' && statusCell.classList.contains('status-inactive'))) {
                    row.style.display = '';
                } else {
                    row.style.display = 'none';
                }
            });
        });

        // Initialize with sample data
        renderData(sampleData);
    </script>
